function countMatches(text, patterns) {
  if (!text) return 0;
  return patterns.reduce(
    (score, regex) => score + (regex.test(text) ? 1 : 0),
    0
  );
}

function addPatternScore(scores, key, text, patterns, weight) {
  scores[key] += countMatches(text, patterns) * weight;
